<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $base = App\Core\Config::url('/campeonatos/' . $championship['slug']); ?>
<section class="portal-page-heading"><p class="eyebrow"><?= $e($championship['name']) ?></p><?php if ($team['shield_path']): ?><img class="portal-shield portal-shield-large" src="<?= $e($base . '/equipes/' . rawurlencode($team['slug']) . '/escudo') ?>" alt="Escudo de <?= $e($team['name']) ?>"><?php endif; ?><h1><?= $e($team['name']) ?></h1><p><?= $e($team['description'] ?: trim(($team['city'] ?: '') . ' ' . ($team['state'] ?: ''))) ?></p></section><section><div class="section-heading"><h2>Elenco oficial</h2><a href="<?= $e($base . '/atletas') ?>">Todos os atletas</a></div><div class="portal-card-grid"><?php foreach ($team['athletes'] as $athlete): ?><a class="portal-card" href="<?= $e($base . '/atletas/' . $athlete['id']) ?>"><?php if ($athlete['photo_path']): ?><img class="portal-athlete-photo" src="<?= $e($base . '/atletas/' . $athlete['id'] . '/foto') ?>" alt="Foto de <?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?>"><?php endif; ?><h2><?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?></h2><p><?= $e($athlete['position_name']) ?> · <?= $e($athlete['preferred_number'] ?: '-') ?></p></a><?php endforeach; ?></div><?php if (!$team['athletes']): ?><p>Elenco oficial ainda nao publicado.</p><?php endif; ?></section>
